//! One source-derived precision bit on the complete structurally admitted late
//! forward fold family. This is a capacity repair, not an exact-only rewrite.
//! Every inherited pass runs first. Whole old regions, balanced scopes, existing
//! quantum capacity, and classical temporal interfaces are checked again here.
use crate::circuit::{BitId,Op,OperationType as K,QubitId,RegisterId};
use std::collections::{BTreeMap,BTreeSet};
const NONE:u64=u64::MAX;
const DATA:&[u8]=include_bytes!("precision_family.bin");
#[derive(Clone)]struct Spec{tick:usize,prefix:usize,suffix:usize,payload:u64,old:Vec<Op>,new:Vec<Op>}
fn decode(data:&[u8])->Vec<Op>{assert_eq!(data.len()%56,0);data.chunks_exact(56).map(|b|{let u=|i|u64::from_le_bytes(b[i..i+8].try_into().unwrap());let kind=match u(0){0=>K::Neg,1=>K::Register,2=>K::AppendToRegister,3=>K::BitInvert,4=>K::BitStore0,5=>K::BitStore1,6=>K::X,7=>K::Z,8=>K::CX,9=>K::CZ,10=>K::Swap,11=>K::R,12=>K::Hmr,13=>K::CCX,14=>K::CCZ,15=>K::PushCondition,16=>K::PopCondition,17=>K::DebugPrint,_=>panic!("precision operation kind")};let o=Op{kind,q_control2:QubitId(u(8)),q_control1:QubitId(u(16)),q_target:QubitId(u(24)),c_target:BitId(u(32)),c_condition:BitId(u(40)),r_target:RegisterId(u(48))};o.validate();o}).collect()}
fn specs()->Vec<Spec>{assert_eq!(&DATA[..8],b"PRECFAM1");let u=|p|u32::from_le_bytes(DATA[p..p+4].try_into().unwrap())as usize;let n=u(8);assert_eq!(n,29,"complete admitted family must be present");let flat=12+32*n;assert!(flat<=DATA.len());(0..n).map(|i|{let p=12+32*i;let tick=u(p);let prefix=u(p+4);let suffix=u(p+8);let payload=u(p+12)as u64;let no=u(p+16);let nn=u(p+20);let a=flat+56*u(p+24);let b=flat+56*u(p+28);Spec{tick,prefix,suffix,payload,old:decode(&DATA[a..a+56*no]),new:decode(&DATA[b..b+56*nn])}}).collect()}
fn depth_after(d:usize,o:&Op)->usize{match o.kind{K::PushCondition=>d+1,K::PopCondition=>d.checked_sub(1).expect("precision scope underflow"),_=>d}}
fn quantum(ops:&[Op])->BTreeSet<u64>{ops.iter().flat_map(|o|[o.q_control2.0,o.q_control1.0,o.q_target.0]).filter(|&q|q!=NONE).collect()}
fn writes(ops:&[Op])->BTreeSet<u64>{ops.iter().filter(|o|matches!(o.kind,K::BitInvert|K::BitStore0|K::BitStore1|K::Hmr)).map(|o|o.c_target.0).collect()}
fn reads(ops:&[Op])->BTreeSet<u64>{ops.iter().flat_map(|o|[o.c_condition.0,if o.kind==K::BitInvert{o.c_target.0}else{NONE}]).filter(|&b|b!=NONE).collect()}
type Monomial=BTreeSet<u64>;type Poly=BTreeSet<Monomial>;
fn p0()->Poly{Poly::new()}fn p1()->Poly{[Monomial::new()].into_iter().collect()}
fn var(tag:u64,id:u64)->Poly{assert!(id<(1<<56));[[tag<<56|id].into_iter().collect()].into_iter().collect()}
fn xor(a:&Poly,b:&Poly)->Poly{a.symmetric_difference(b).cloned().collect()}
fn and(a:&Poly,b:&Poly)->Poly{let mut out=Poly::new();for x in a{for y in b{let m:Monomial=x.union(y).copied().collect();if !out.insert(m.clone()){out.remove(&m);}assert!(out.len()<=200000,"precision classical proof resource limit");}}out}
fn get(b:&BTreeMap<u64,Poly>,wire:u64)->Poly{b.get(&wire).cloned().unwrap_or_else(||var(0,wire))}
// HMR's outcome is independent of the quantum value. Sharing ONLY identical
// prefix/suffix MR roles proves the live classical boundary even when all
// changed-middle draws are independent between the two precision choices.
fn classical(ops:&[Op],prefix:usize,suffix:usize,tag:u64)->BTreeMap<u64,Poly>{let mut bits=BTreeMap::new();let mut base=p1();let mut stack=Vec::new();for(i,o)in ops.iter().enumerate(){let c=if o.c_condition.0==NONE{base.clone()}else{and(&base,&get(&bits,o.c_condition.0))};match o.kind{K::PushCondition=>{stack.push(base);base=c;},K::PopCondition=>base=stack.pop().expect("precision unbalanced classical scope"),K::BitInvert|K::BitStore0|K::BitStore1|K::Hmr=>{let old=get(&bits,o.c_target.0);let next=if o.kind==K::BitInvert{xor(&old,&c)}else{let value=match o.kind{K::BitStore0=>p0(),K::BitStore1=>p1(),_=>if i<prefix{var(1,i as u64)}else if i>=ops.len()-suffix{var(2,(ops.len()-1-i)as u64)}else{var(tag,i as u64)}};xor(&old,&and(&c,&xor(&old,&value)))};bits.insert(o.c_target.0,next);},_=>{}}}assert!(stack.is_empty(),"precision scope does not close");bits}
fn stable_external(i:usize,regions:&[(usize,usize,usize)]){for&(a,b,prefix)in regions{if a<=i&&i<b{assert!(i-a<prefix,"precision classical interface crosses another changed region");}}}
// Every bit live outside the region must retain exactly the same Boolean
// function under the prefix/suffix coupling. An unequal final version is
// allowed only if an unchanged unconditional overwrite precedes ANY read.
fn live_bits(ops:&[Op],end:usize,bits:&BTreeSet<u64>,regions:&[(usize,usize,usize)])->BTreeSet<u64>{let mut pending=bits.clone();let mut live=BTreeSet::new();let mut d=0;for(i,o)in ops.iter().enumerate().skip(end){let mut rd=BTreeSet::new();if o.c_condition.0!=NONE{rd.insert(o.c_condition.0);}if o.kind==K::BitInvert{rd.insert(o.c_target.0);}let found:Vec<_>=pending.intersection(&rd).copied().collect();for bit in found{stable_external(i,regions);live.insert(bit);pending.remove(&bit);}if d==0&&o.c_condition.0==NONE&&matches!(o.kind,K::BitStore0|K::BitStore1|K::Hmr)&&pending.remove(&o.c_target.0){stable_external(i,regions);}d=depth_after(d,o);if pending.is_empty(){break;}}live}
fn check_spec(s:&Spec,nq:u64){assert!(!s.old.is_empty()&&!s.new.is_empty());let prefix=s.old.iter().zip(&s.new).take_while(|(a,b)|a==b).count();let suffix=s.old.iter().rev().zip(s.new.iter().rev()).take_while(|(a,b)|a==b).count().min(s.old.len()-prefix);assert_eq!((prefix,suffix),(s.prefix,s.suffix),"precision source prefix/suffix mismatch");assert_eq!(writes(&s.old),writes(&s.new),"precision bit clobber interface");assert_eq!(reads(&s.old),reads(&s.new),"precision incoming bit interface");let oq=quantum(&s.old);let nqset=quantum(&s.new);assert_eq!(nqset.difference(&oq).copied().collect::<BTreeSet<_>>(),[s.payload].into_iter().collect(),"precision scratch/next-payload interface");assert!(nqset.iter().all(|q|*q<nq),"precision adds physical quantum capacity");let mut d=0;for o in &s.new{d=depth_after(d,o);}assert_eq!(d,0);}
pub fn run(ops:Vec<Op>)->Vec<Op>{let specs=specs();let nq=quantum(&ops).into_iter().max().unwrap()+1;let mut locations=Vec::new();for(sid,s)in specs.iter().enumerate(){check_spec(s,nq);let at:Vec<_>=ops.windows(s.old.len()).enumerate().filter(|(_,w)|*w==s.old.as_slice()).map(|(i,_)|i).collect();assert_eq!(at.len(),1,"precision complete region missing/edited/ambiguous at tick{}",s.tick);locations.push((at[0],at[0]+s.old.len(),sid));}locations.sort_unstable();assert!(locations.windows(2).all(|w|w[0].1<=w[1].0),"precision regions overlap");let boundary:BTreeSet<_>=locations.iter().flat_map(|r|[r.0,r.1]).collect();let mut depth=0;for(i,o)in ops.iter().enumerate(){if boundary.contains(&i){assert_eq!(depth,0,"precision boundary crosses original scope snapshot");}depth=depth_after(depth,o);}assert_eq!(depth,0);let regions:Vec<_>=locations.iter().map(|&(a,b,sid)|(a,b,specs[sid].prefix)).collect();for&(at,end,sid)in &locations{let s=&specs[sid];let live=live_bits(&ops,end,&writes(&s.old),&regions);let old=classical(&s.old,s.prefix,s.suffix,3);let new=classical(&s.new,s.prefix,s.suffix,4);for bit in &live{assert_eq!(get(&old,*bit),get(&new,*bit),"precision live classical version changed at tick{} bit{}",s.tick,bit);}eprintln!("PRECISION_FAMILY tick={} at={} old={} new={} extra_scratch_q=0 live_bits={} exact_classical_boundary=true",s.tick,at,s.old.len(),s.new.len(),live.len());}
let mut out=Vec::with_capacity(ops.len()+specs.iter().map(|s|s.new.len()-s.old.len()).sum::<usize>());let mut iter=ops.into_iter().enumerate();let mut next=0;while let Some((i,o))=iter.next(){if next<locations.len()&&i==locations[next].0{let(_,end,sid)=locations[next];for _ in i+1..end{iter.next().unwrap();}out.extend_from_slice(&specs[sid].new);next+=1;}else{out.push(o);}}assert_eq!(next,specs.len());eprintln!("PRECISION_FAMILY_COMPLETE admitted={} skipped=0 source_defined=true tables_retained=true",next);out}

#[cfg(test)]mod tests{use super::*;fn op(k:K,t:u64,bt:u64,cc:u64)->Op{let mut o=Op::empty();o.kind=k;o.q_target=QubitId(t);o.c_target=BitId(bt);o.c_condition=BitId(cc);o}
#[test]fn classical_snapshot_retains_prior_bit(){let seq=[op(K::PushCondition,NONE,NONE,0),op(K::Hmr,0,0,NONE),op(K::BitStore1,NONE,1,NONE),op(K::PopCondition,NONE,NONE,NONE)];let p=classical(&seq,0,0,3);assert_eq!(get(&p,1),xor(&var(0,1),&and(&var(0,0),&xor(&var(0,1),&p1()))));}
#[test]fn suffix_overwrite_restores_live_interface(){let old=[op(K::Hmr,0,0,NONE),op(K::Hmr,1,0,NONE)];let new=[op(K::Hmr,2,0,NONE),op(K::Hmr,0,0,NONE),op(K::Hmr,1,0,NONE)];assert_eq!(get(&classical(&old,0,1,3),0),get(&classical(&new,0,1,4),0));}
#[test]fn independent_changed_draw_is_not_proved_equal(){let seq=[op(K::Hmr,0,0,NONE)];assert_ne!(get(&classical(&seq,0,0,3),0),get(&classical(&seq,0,0,4),0));}
#[test]fn source_specs_validate_physical_interfaces(){for s in specs(){check_spec(&s,1234);}}
#[test]fn live_read_precedes_unconditional_kill(){let seq=[op(K::X,0,NONE,4),op(K::Hmr,0,4,NONE)];assert_eq!(live_bits(&seq,0,&[4].into_iter().collect(),&[]),[4].into_iter().collect());}
#[test]fn unconditional_kill_makes_prior_version_dead(){let seq=[op(K::Hmr,0,4,NONE),op(K::X,0,NONE,4)];assert!(live_bits(&seq,0,&[4].into_iter().collect(),&[]).is_empty());}
#[test]#[should_panic]fn incompatible_spec_is_rejected(){let mut s=specs().remove(0);s.payload+=1;check_spec(&s,1234);}
#[test]#[should_panic]fn missing_quantum_capacity_is_rejected(){check_spec(&specs()[0],300);}
#[test]#[should_panic]fn live_interface_in_other_changed_region_rejected(){stable_external(12,&[(10,20,1)]);}
}
